import{_ as a,c as i,o as n,ah as t}from"./chunks/framework.DaDXF32t.js";const u=JSON.parse('{"title":"Installer Full-Screen, Dependency Cache, and Download Ranking Design","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-08-02-installer-fullscreen-cache-download-ranking-design.md","filePath":"superpowers/specs/2026-08-02-installer-fullscreen-cache-download-ranking-design.md","lastUpdated":1785749755000}'),r={name:"superpowers/specs/2026-08-02-installer-fullscreen-cache-download-ranking-design.md"};function s(o,e,l,d,c,h){return n(),i("div",null,e[0]||(e[0]=[t(`<h1 id="installer-full-screen-dependency-cache-and-download-ranking-design" tabindex="-1">Installer Full-Screen, Dependency Cache, and Download Ranking Design <a class="header-anchor" href="#installer-full-screen-dependency-cache-and-download-ranking-design" aria-label="Permalink to “Installer Full-Screen, Dependency Cache, and Download Ranking Design”">​</a></h1><h2 id="_1-scope" tabindex="-1">1. Scope <a class="header-anchor" href="#_1-scope" aria-label="Permalink to “1. Scope”">​</a></h2><p>This increment improves the native C++ installer on <code>feat/cpp-tui-installer</code> without changing its repository deployment model. It covers seven user-visible requirements:</p><ol><li>Fill the current terminal viewport with the TUI.</li><li>Skip dependency resolution and synchronization when a verified SHA-256 dependency stamp is unchanged.</li><li>Replace the title and restore the historical welcome, author, license, repository, and community information.</li><li>Keep a managed installation usable after its containing directory is renamed or moved.</li><li>Create <code>setup.toml</code> as soon as installation begins.</li><li>Embed the project icon in the Windows executable.</li><li>Benchmark uv, CPython, and PyPI sources only when the corresponding network operation is required, including the supplied CNB mirrors.</li></ol><p>The existing constraints remain in force: <code>setup.toml</code> is the only configuration file, all managed uv data stays below the installation root, child command output is captured through PTY chunks, <code>MAIN_REPO_SRC_DEV</code> is excluded, and <code>baas-cdn.kiramei.workers.dev</code> is never used.</p><h2 id="_2-confirmed-root-causes" tabindex="-1">2. Confirmed root causes <a class="header-anchor" href="#_2-confirmed-root-causes" aria-label="Permalink to “2. Confirmed root causes”">​</a></h2><h3 id="_2-1-repeated-dependency-work" tabindex="-1">2.1 Repeated dependency work <a class="header-anchor" href="#_2-1-repeated-dependency-work" aria-label="Permalink to “2.1 Repeated dependency work”">​</a></h3><p>The current implementation runs <code>uv python install</code>, <code>uv pip compile</code>, and <code>uv pip sync</code> on every invocation. It then runs <code>uv cache clean</code>, deleting the artifacts that would otherwise accelerate later work. Although the earlier design mentioned a requirements cache, no dependency stamp is implemented.</p><h3 id="_2-2-rename-failure" tabindex="-1">2.2 Rename failure <a class="header-anchor" href="#_2-2-rename-failure" aria-label="Permalink to “2.2 Rename failure”">​</a></h3><p>A real renamed-installation probe reproduced the failure. The managed <code>.venv/pyvenv.cfg</code> retained the old absolute CPython <code>home</code> path. The installer considered the environment reusable because it checked only <code>pyvenv.cfg</code> existence and a marker containing the Python version. <code>uv pip sync</code> then rejected the broken environment.</p><p>The fix must repair relocatable metadata before deciding whether dependency work can be skipped. Merely retrying uv or recreating every environment would hide the cause and discard otherwise valid installations.</p><h3 id="_2-3-slow-downloads" tabindex="-1">2.3 Slow downloads <a class="header-anchor" href="#_2-3-slow-downloads" aria-label="Permalink to “2.3 Slow downloads”">​</a></h3><p>The current uv path tries sources in a fixed order. Source ranking helpers exist but are not connected to uv, CPython, or PyPI setup. The supplied CNB release assets are not in the source lists.</p><h2 id="_3-tui-layout-and-identity" tabindex="-1">3. TUI layout and identity <a class="header-anchor" href="#_3-tui-layout-and-identity" aria-label="Permalink to “3. TUI layout and identity”">​</a></h2><p><code>ScreenInteractive::Fullscreen()</code> remains the terminal backend. The renderer will stop centering a minimum-sized panel and instead return a bordered element constrained to the full available width and height. The setup page and installation page both fill the viewport. The installation log remains the flexible region and receives all remaining vertical space.</p><p>The header is exactly:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    ____  ___    ___   _____</span></span>
<span class="line"><span>   / __ )/   |  /   | / ___/</span></span>
<span class="line"><span>  / __  / /| | / /| | \\__ \\</span></span>
<span class="line"><span> / /_/ / ___ |/ ___ |___/ /</span></span>
<span class="line"><span>/_____/_/  |_/_/  |_/____/</span></span></code></pre></div><p>The selected system language controls the welcome line:</p><ul><li>English: <code>Welcome to BlueArchive Auto Script!</code></li><li>Simplified Chinese: <code>欢迎使用蔚蓝档案自动脚本！</code></li></ul><p>The header also restores these stable project details from the historical installer:</p><ul><li><code>Developed by pur1fying</code></li><li><code>LICENSE: GPL-3.0</code></li><li><code>https://github.com/pur1fying/blue_archive_auto_script</code></li><li><code>Official QQ Group: 658302636</code></li></ul><p>These details are visible in both supported languages. Tests render a fixed terminal-sized screen and verify that the outer border reaches all four edges, the five title rows are present, and the localized welcome and metadata are visible.</p><h2 id="_4-immediate-configuration-durability" tabindex="-1">4. Immediate configuration durability <a class="header-anchor" href="#_4-immediate-configuration-durability" aria-label="Permalink to “4. Immediate configuration durability”">​</a></h2><p>After the user presses Start, the selected MirrorChyan setting is copied into the in-memory configuration and <code>save_config_atomic</code> runs before repository preparation, source probes, or downloads. This guarantees that <code>setup.toml</code> appears immediately.</p><p>The early save retains the last known successful repository SHA values. A later successful installation atomically saves both new repository versions. If deployment fails, file rollback restores managed files while the newly created or updated <code>setup.toml</code> remains, containing the selected settings and old SHA values. A configuration write failure stops installation before any live deployment work.</p><h2 id="_5-dependency-stamp-and-relocation-repair" tabindex="-1">5. Dependency stamp and relocation repair <a class="header-anchor" href="#_5-dependency-stamp-and-relocation-repair" aria-label="Permalink to “5. Dependency stamp and relocation repair”">​</a></h2><h3 id="_5-1-stamp-format" tabindex="-1">5.1 Stamp format <a class="header-anchor" href="#_5-1-stamp-format" aria-label="Permalink to “5.1 Stamp format”">​</a></h3><p>Successful dependency synchronization writes <code>&lt;root&gt;/.baas-installer/dependencies-v1.sha256</code>. The fingerprint is SHA-256 over a canonical byte sequence containing:</p><ul><li>dependency-stamp schema version <code>1</code>;</li><li>the selected platform;</li><li>the complete applicable requirements file bytes;</li><li>configured Python version;</li><li>portable or custom runtime mode;</li><li>custom interpreter path when custom mode is used; and</li><li>the generated lock file digest.</li></ul><p>The persisted record contains the input digest and lock digest. Paths for a portable runtime are not included, so moving the installation does not invalidate the stamp. The record is written atomically only after synchronization succeeds.</p><h3 id="_5-2-cache-hit-validation" tabindex="-1">5.2 Cache-hit validation <a class="header-anchor" href="#_5-2-cache-hit-validation" aria-label="Permalink to “5.2 Cache-hit validation”">​</a></h3><p>Before invoking uv, the installer checks:</p><ul><li>the requirements and lock files exist;</li><li>their freshly computed digests match the stamp;</li><li>the configured runtime mode and Python version match;</li><li>for portable mode, the managed marker, virtual-environment Python executable, managed CPython directory, and <code>pyvenv.cfg</code> exist; or</li><li>for custom mode, the configured interpreter exists.</li></ul><p>If all checks pass, dependency resolution and synchronization are skipped. The TUI and log explicitly report a dependency-cache hit. No uv, CPython, PyPI probe, or cache cleanup command runs.</p><h3 id="_5-3-relocation-repair" tabindex="-1">5.3 Relocation repair <a class="header-anchor" href="#_5-3-relocation-repair" aria-label="Permalink to “5.3 Relocation repair”">​</a></h3><p>For an installer-managed environment, <code>pyvenv.cfg</code> is parsed before cache validation. When its <code>home</code>, <code>executable</code>, or <code>command</code> fields point below an old installation root, the old managed prefix is replaced with the current managed CPython path and the file is atomically rewritten. Unrelated external interpreter paths are never rewritten.</p><p>After repair, the virtual-environment interpreter is checked for existence. A valid dependency stamp can then skip uv completely. If repair cannot produce a valid environment, the normal cache-miss path recreates the virtual environment and synchronizes from the existing compiled lock where safe.</p><h3 id="_5-4-cache-miss" tabindex="-1">5.4 Cache miss <a class="header-anchor" href="#_5-4-cache-miss" aria-label="Permalink to “5.4 Cache miss”">​</a></h3><p>On a missing or different stamp, the installer:</p><ol><li>ensures uv exists;</li><li>ensures the requested managed CPython exists, when portable mode is selected;</li><li>creates or repairs the virtual environment;</li><li>benchmarks PyPI candidates;</li><li>compiles the requirements file;</li><li>synchronizes the compiled lock; and</li><li>writes the new stamp.</li></ol><p>The installer no longer runs <code>uv cache clean</code> after success. Operational failures do not update the stamp.</p><h2 id="_6-on-demand-source-benchmarking" tabindex="-1">6. On-demand source benchmarking <a class="header-anchor" href="#_6-on-demand-source-benchmarking" aria-label="Permalink to “6. On-demand source benchmarking”">​</a></h2><p>Source benchmarking uses concurrent short HTTP probes and stable latency ordering. HEAD is attempted first, followed by a byte-range GET when HEAD is unsupported. Probes use in-process libcurl and report sanitized progress through the unified installer log; they do not start child commands or expose credentials.</p><p>Benchmarking is strictly demand-driven:</p><ul><li>uv candidates are probed only when the uv executable is missing;</li><li>CPython candidates are probed only when the requested managed Python is missing;</li><li>PyPI candidates are probed only when the dependency stamp is invalid;</li><li>a complete dependency-cache hit runs none of these probes.</li></ul><p>The ranked list is tried in order. A download or install failure immediately falls through to the next ranked candidate. Actual external uv and curl operations continue to run through the PTY-backed process runner so their chunked progress remains complete.</p><h3 id="_6-1-uv-candidates" tabindex="-1">6.1 uv candidates <a class="header-anchor" href="#_6-1-uv-candidates" aria-label="Permalink to “6.1 uv candidates”">​</a></h3><p>Each base URL is joined with the platform uv archive filename. The supplied CNB source is added ahead of the existing stable fallbacks:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://cnb.cool/kiramei/baas-tauri/-/releases/download/uv-down</span></span></code></pre></div><p>The downloaded archive must still match the pinned official uv 0.5.11 SHA-256 before extraction, regardless of which mirror wins.</p><h3 id="_6-2-cpython-candidates" tabindex="-1">6.2 CPython candidates <a class="header-anchor" href="#_6-2-cpython-candidates" aria-label="Permalink to “6.2 CPython candidates”">​</a></h3><p>The supplied CNB Python release base is added ahead of the existing stable fallbacks:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://cnb.cool/kiramei/baas-tauri/-/releases/download</span></span></code></pre></div><p>It is passed to uv as <code>UV_PYTHON_INSTALL_MIRROR</code>, preserving uv&#39;s expected release-tag suffix. GitHub, Gitee, and supported GitHub proxy bases remain fallbacks. A source that lacks the requested platform asset simply fails its probe or install and is skipped.</p><h3 id="_6-3-pypi-candidates" tabindex="-1">6.3 PyPI candidates <a class="header-anchor" href="#_6-3-pypi-candidates" aria-label="Permalink to “6.3 PyPI candidates”">​</a></h3><p>Configured sources retain priority as candidates but participate in the same benchmark. The default Aliyun, Douban, Huawei, Tencent, 163, Tsinghua, USTC, and official PyPI sources remain available. No ranking or network access occurs on a dependency-cache hit.</p><h2 id="_7-windows-executable-icon" tabindex="-1">7. Windows executable icon <a class="header-anchor" href="#_7-windows-executable-icon" aria-label="Permalink to “7. Windows executable icon”">​</a></h2><p>A Windows resource script embeds <code>deploy/installer/logo.ico</code> as the executable&#39;s primary icon. CMake enables and compiles the resource only on Windows, so Linux and macOS builds remain unchanged. A Windows-only integration test calls the Win32 icon extraction API on the built installer and fails when no embedded icon can be loaded.</p><h2 id="_8-testing-and-release-verification" tabindex="-1">8. Testing and release verification <a class="header-anchor" href="#_8-testing-and-release-verification" aria-label="Permalink to “8. Testing and release verification”">​</a></h2><p>Test-driven implementation adds focused failures before each production change:</p><ul><li>rendered TUI consumes the complete terminal viewport;</li><li>title, localized welcome, author, license, repository, and QQ group render correctly;</li><li><code>setup.toml</code> exists before either repository preparation callback begins;</li><li>a matching dependency stamp produces zero uv commands and zero source probes;</li><li>a changed requirements byte invalidates the stamp and runs compile/sync;</li><li>a moved managed environment rewrites only old managed paths and then hits the cache;</li><li>missing uv, CPython, and invalid dependencies trigger only their respective benchmark families;</li><li>CNB candidates are present while the retired BAAS CDN remains absent;</li><li>source probes run concurrently and downloads follow ranked order;</li><li>the Windows release executable exposes the embedded icon.</li></ul><p>Fresh verification includes both existing local Windows builds, the complete CTest suite, a disposable migration, and a whole-directory rename followed by dependency imports and BAAS launch. Linux verification uses the authorized test directory <code>/home/kiramei/Workspace/Tests/BAAS</code>; connection credentials remain runtime-only and must not be written to files, logs, shell history, commits, process arguments, or artifacts. Cross-platform GitHub Actions remains required before completion.</p><h2 id="_9-security-and-rollback" tabindex="-1">9. Security and rollback <a class="header-anchor" href="#_9-security-and-rollback" aria-label="Permalink to “9. Security and rollback”">​</a></h2><ul><li>MirrorChyan CDKs and external test credentials remain secret and use the existing redaction boundary.</li><li>The retired BAAS CDN is rejected by tests across every source family.</li><li>Downloaded uv archives retain pinned digest verification.</li><li>Dependency stamps are never written until the matching environment is synchronized successfully.</li><li>Relocation repair uses atomic replacement and is limited to an installer-managed virtual environment.</li><li>Early <code>setup.toml</code> creation does not authorize early repository SHA persistence.</li><li>Existing untracked worktree files and external installations remain outside commits.</li></ul>`,64)]))}const m=a(r,[["render",s]]);export{u as __pageData,m as default};
